document.addEventListener("DOMContentLoaded",function(){
  const refs=Object.create(null);
  const el=id=>refs[id]||(refs[id]=document.getElementById(id));
  const number=/-?(?:\d*\.?\d+)(?:e[-+]?\d+)?/gi;
  const pair=/(-?(?:\d*\.?\d+))[\s,]+(-?(?:\d*\.?\d+))/g;
  const f=n=>String(Math.round(n*1000)/1000);
  const clamp=n=>Math.max(0,Math.min(1,n));
  const set=(id,name,value)=>el(id).setAttribute(name,value);

  function morph(id,target){
    const node=el(id);
    const source=node.getAttribute("d");
    const a=source.match(number).map(Number);
    const b=target.match(number).map(Number);
    return function(k){
      let i=0;
      node.setAttribute("d",source.replace(number,function(){
        const value=a[i]+(b[i]-a[i])*k;
        i++;
        return f(value);
      }));
    };
  }

  function warp(id){
    const node=el(id),source=node.getAttribute("d");
    return function(dx,dy){
      node.setAttribute("d",source.replace(pair,function(all,xx,yy){
        const x=Number(xx),y=Number(yy);
